function radioElements(e){const t=document.querySelectorAll(e);t.forEach((function(t){t.addEventListener("click",(function(){const t=this.closest(".group");if(!t)return;const l=t.querySelectorAll(e);l.forEach((function(e){e.classList.remove("active")}));this.classList.add("active")}))}))}function changeToProductUrl(){const e=window.location.pathname.split("/").slice(0,2).join("/");const t="/product";window.history.pushState(null,"",e+t)}function createEtc(){const e=document.createElement("i");e.classList.add("bi","bi-three-dots");return e}function hideModal(e){document.querySelector(e).classList.remove("active")}function closeModal(e){e.currentTarget.closest(".modall").classList.remove("active")}function setUpPagination(e){const t=document.querySelector(e);const l=t.querySelectorAll(".page-item .page-link");var o=l.length;const c=t.querySelectorAll(".etc");l[0].classList.add("active");if(o>4){c.forEach((e=>{e.style.display="block"}));l.forEach((e=>{e.style.display="none";e.addEventListener("click",(function(e){updatePagination("#order-pagination",e.currentTarget.getAttribute("data-value")-1)}))}));l[0].style.display="block";l[1].style.display="block";l[2].style.display="block";l[3].style.display="block";l[o-1].style.display="block"}else{c.forEach((e=>{e.style.display="none"}))}}function updatePagination(e,t){const l=document.querySelector(e);const o=l.querySelectorAll(".page-item .page-link");o.forEach((e=>{if(e.classList.contains("active"))e.classList.remove("active")}));var c=o.length;if(c>4){o.forEach((e=>{e.style.display="none"}));o[0].style.display="block";o[c-1].style.display="block";if(t<=2){o[1].style.display="block";o[2].style.display="block"}else if(t>=c-1){o[c-2].style.display="block";o[c-3].style.display="block"}else{o[t-2].style.display="block";o[t-1].style.display="block";o[t].style.display="block"}}l.querySelector(`.page-item .page-link[data-value="${t}"]`).classList.add("active")}function nextPage(e){e.preventDefault();const t=e.currentTarget.closest(".group");const l=t.querySelectorAll(".page-item .page-link");var o=t.querySelector(".page-item .page-link.active").getAttribute("data-value");if(o<l.length){l[o].click()}else{showInfoToast2("Đã tới cuối danh sách!","none")}}function previousPage(e){e.preventDefault();const t=e.currentTarget.closest(".group");const l=t.querySelectorAll(".page-item .page-link");var o=t.querySelector(".page-item .page-link.active").getAttribute("data-value")-1;if(o>0){l[o-1].click()}else{showInfoToast2("Đã tới đầu danh sách!","none")}}function setDefaultOption(e){document.querySelectorAll('select[name="'+e+'"]').forEach((e=>{const t=e.getAttribute("data-default");e.value=t}))}function setSelectedOption(e,t){document.querySelector("select#"+e).value=t}function openModal(e){document.querySelector(e).classList.add("active")}function addClassLocked(e){document.querySelector(e).classList.add("locked")}function removeClassLocked(e){document.querySelector(e).classList.remove("locked")}function hide(e){document.querySelector(e).style.display="none"}function setInfosStatus(e,t){const l=e.querySelectorAll("input");const o=e.querySelectorAll("select");var t=!t;l.forEach((e=>{e.readOnly=t}));o.forEach((e=>{e.disabled=t}));if(e.querySelector("select[name='action']"))e.querySelector("select[name='action']").disabled=false}function scrollToBottom(){window.scrollTo({top:document.body.scrollHeight,behavior:"smooth"})}function refresh(){location.reload()}function setSearchValue(e,t){document.querySelector(e).value=t}